#include <bits/stdc++.h>
using namespace std;

int n;
long long S, ways = 0;
vector<long long> a;

void go(int i, long long sum) {
    if (i == n) {
        if (sum == S) ways++;
        return;
    }
    go(i + 1, sum);
    go(i + 1, sum + a[i]);
}

int main() {
    cin >> n >> S;
    a.resize(n);
    for (auto &x : a) cin >> x;
    go(0, 0);
    cout << ways << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> c(n + 1, 0), dp(n + 1, 0);
    for (int i = 1; i <= n; i++) cin >> c[i];
    dp[0] = 0;
    dp[1] = c[1];
    for (int i = 2; i <= n; i++)
        dp[i] = c[i] + min(dp[i - 1], dp[i - 2]);
    cout << dp[n] << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<long long>> dp(n, vector<long long>(m));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            long long x;
            cin >> x;
            if (i == 0 && j == 0) dp[i][j] = x;
            else if (i == 0) dp[i][j] = dp[i][j - 1] + x;
            else if (j == 0) dp[i][j] = dp[i - 1][j] + x;
            else dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + x;
        }
    cout << dp[n - 1][m - 1] << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> g(n);
    for (auto &row : g) cin >> row;

    int sx = 0, sy = 0, fx = 0, fy = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            if (g[i][j] == 'S') { sx = i; sy = j; }
            if (g[i][j] == 'F') { fx = i; fy = j; }
        }

    vector<vector<int>> dist(n, vector<int>(m, -1));
    queue<pair<int, int>> q;
    dist[sx][sy] = 0;
    q.push({sx, sy});
    int dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx < 0 || ny < 0 || nx >= n || ny >= m) continue;
            if (g[nx][ny] == '#' || dist[nx][ny] != -1) continue;
            dist[nx][ny] = dist[x][y] + 1;
            q.push({nx, ny});
        }
    }
    cout << dist[fx][fy] << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<bool> prime(n + 1, true);
    int cnt = 0;
    for (long long i = 2; i <= n; i++) {
        if (!prime[i]) continue;
        cnt++;
        for (long long j = i * i; j <= n; j += i) prime[j] = false;
    }
    cout << cnt << "\n";
    return 0;
}
